def parse_qs_simple(qs: str) -> dict:
    if not qs:
        return {}
    result = {}
    pairs = qs.split('&')
    for pair in pairs:
        if '=' in pair:
            key, val = pair.split('=', 1)
        else:
            key, val = pair, ''
        if key in result:
            if isinstance(result[key], list):
                result[key].append(val)
            else:
                result[key] = [result[key], val]
        else:
            result[key] = val
    return result
